  const [mode, setMode] = useMode();
  const [dismissed, setDismissed] = useState<string | null>(null);
  const [visited, setVisited] = useState(() => new Set<string>());
  if (mode && !visited.has(mode)) setVisited(new Set(visited).add(mode));

  return (
    <LiveContext value={live}>
      <MotionConfig reducedMotion="user" transition={spring}>
        <Header mode={mode} onMode={setMode} />
        {modes.map(
          (m) =>
            visited.has(m) && (
              <motion.main
                key={m}
                inert={mode !== m}
                aria-hidden={mode !== m}
                // invisible instead of display:none keeps chart sizes so returning to a view does not re-measure every chart
                className={mode === m ? "" : "pointer-events-none invisible absolute inset-x-0 top-0 h-0 overflow-hidden"}
                initial={{ opacity: 0 }}
                animate={{ opacity: mode === m ? 1 : 0 }}
                transition={{ duration: 0.18, ease: "easeOut" }}
              >
                {m === "family" ? <FamilyView dismissed={dismissed} onDismiss={setDismissed} /> : <PhysicianView />}
              </motion.main>
            ),
        )}
      </MotionConfig>
    </LiveContext>
  );
}

  return (
    <div className="mx-auto max-w-3xl space-y-5 px-6 pb-16">
      <Hero status={status} events={events} now={now} connection={connection} />
      <TodayStrip events={events} today={today} now={now} loading={eventsLoading} />
      <WeeklyStability daily={daily.data} loading={daily.loading} />
      <WeeklySummary report={report} loading={reports.loading} />
      <NearTripSheet alert={showAlert} onDismiss={() => alert && onDismiss(alert.id)} />
    </div>
  );
}
