import { motion } from "motion/react";
import { press, pressTransition, spring } from "./motion";

export function SectionNav<T extends string>({
  label,
  sections,
  value,
  onChange,
  id,
}: {
  label: string;
  sections: { id: T; label: string }[];
  value: T;
  onChange: (value: T) => void;
  id: string;
}) {
