                    transition={spring}
                    className="absolute inset-0 rounded-full bg-surface shadow-[0_1px_3px_rgb(0_0_0/0.12)]"
                  />
                )}
                <span className="relative">{section.label}</span>
              </motion.button>
            </li>
          );
