import { motion } from "motion/react";
import { useState, type ReactNode } from "react";

export function Section({ active, children }: { active: boolean; children: ReactNode }) {
  const [visited, setVisited] = useState(active);
  if (active && !visited) setVisited(true);
  if (!visited) return null;

  return (
    <motion.div
      inert={!active}
      aria-hidden={!active}
      className={active ? "space-y-5" : "pointer-events-none invisible absolute inset-x-0 top-0 h-0 overflow-hidden"}
      initial={{ opacity: 0 }}
      animate={{ opacity: active ? 1 : 0 }}
      transition={{ duration: 0.18, ease: "easeOut" }}
    >
      {children}
    </motion.div>
  );
}
