"use client";

import { AnimatePresence, motion } from "motion/react";
import { memo, startTransition, useEffect, useState, type ReactNode } from "react";
import { Skeleton } from "./Card";
import { spring } from "./motion";

function SectionSkeleton() {
  return (
    <motion.div
      role="status"
      aria-label="Loading section"
      className="space-y-5"
      initial={{ opacity: 1 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.12 }}
    >
      <Skeleton className="h-64 rounded-2xl" />
      <div className="grid gap-5 sm:grid-cols-2">
        <Skeleton className="h-32 rounded-2xl" />
        <Skeleton className="h-32 rounded-2xl" />
      </div>
    </motion.div>
  );
}

export function Sections({ pending, children }: { pending: boolean; children: ReactNode }) {
  return (
    <div className="relative min-w-0" aria-busy={pending}>
      <AnimatePresence>
        {pending && (
          <motion.div key="pending" className="pointer-events-none absolute inset-x-0 top-0 z-10" exit={{ opacity: 0 }} transition={{ duration: 0.12 }}>
            <SectionSkeleton />
          </motion.div>
        )}
      </AnimatePresence>
      {pending && <div className="h-[552px] sm:h-[404px]" />}
      <motion.div
        inert={pending}
        aria-hidden={pending}
        className={pending ? "pointer-events-none absolute inset-x-0 top-0" : "relative"}
        animate={{ opacity: pending ? 0 : 1 }}
        transition={pending ? { duration: 0.12 } : spring}
      >
        {children}
      </motion.div>
    </div>
  );
}

export const Section = memo(function Section({ active, children }: { active: boolean; children: ReactNode }) {
  const [mounted, setMounted] = useState(false);
  const [hidden, setHidden] = useState(!active);
  if (active && hidden) setHidden(false);

  useEffect(() => {
    if (!active || mounted) return;
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => startTransition(() => setMounted(true)));
    });
    return () => cancelAnimationFrame(frame);
  }, [active, mounted]);

  if (!active && !mounted) return null;

  return (
    <motion.div
      inert={!active}
      aria-hidden={!active}
      className={active ? "relative" : `pointer-events-none absolute inset-x-0 top-0 ${hidden ? "invisible h-0 overflow-hidden" : ""}`}
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: active ? 1 : 0, y: active ? 0 : 8 }}
      transition={active ? spring : { duration: 0.12 }}
      onAnimationComplete={() => { if (!active) setHidden(true); }}
      aria-busy={active && !mounted}
    >
      <AnimatePresence>
        {!mounted && (
          <motion.div key="skeleton" className="absolute inset-x-0 top-0" exit={{ opacity: 0 }} transition={{ duration: 0.12 }}>
            <SectionSkeleton />
          </motion.div>
        )}
      </AnimatePresence>
      {!mounted && <div className="h-[552px] sm:h-[404px]" />}
      {mounted && (
        <motion.div className="space-y-5" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={spring}>
          {children}
        </motion.div>
      )}
    </motion.div>
  );
}, (prev, next) => prev.active === next.active && !next.active);

  { value: 90, label: "90 days" },
];

export function PhysicianView() {
  const [section, setSection] = useState<PhysicianSection>("forecast");
  const shown = useDeferredValue(section);
  const today = useToday();
  const [range, setRange] = useState<Range>(30);
  const daily = useFetch<DailyMetrics[]>(paths.daily(180));
  const hourly = useFetch<HourCell[]>(paths.hourly(14));
  const scores = useFetch<ClinicScore[]>(paths.clinicScores());
  const from = today === null ? null : today - (range - 1) * DAY;

  const { setData: setScores, reload: reloadScores } = scores;
  const added = useCallback(
    (s: ClinicScore) => {
      setScores((data) => [...(data ?? []), s]);
      reloadScores();
    },
    [setScores, reloadScores],
  );

  const content = useMemo(() => (
    <>
      <Section active={shown === "forecast"}>
        <ForecastCard />
      </Section>
      <Section active={shown === "overview"}>
        <KpiRow daily={daily.data} loading={daily.loading} today={today} range={range} />
        <div className="grid gap-5 xl:grid-cols-2">
          <LiveCard />
          <EngineCard />
        </div>
      </Section>
      <Section active={shown === "progression"}>
        <ProgressionCard
          daily={daily.data}
          loading={daily.loading}
          scores={scores.data}
          scoresLoading={scores.loading}
          onAdded={added}
        />
        <SimilarDaysCard />
      </Section>
      <Section active={shown === "patterns"}>
        <Heatmap cells={hourly.data} loading={hourly.loading} today={today} />
        <EventsCard from={from} range={range} />
      </Section>
      <Section active={shown === "reports"}>
        <ReportsCard range={range} today={today} />
      </Section>
    </>
  ), [shown, daily.data, daily.loading, today, range, scores.data, scores.loading, added, hourly.data, hourly.loading, from]);

  return (
    <div className="mx-auto grid max-w-[1600px] gap-6 px-6 pt-8 pb-16 lg:grid-cols-[56px_minmax(0,1fr)]">
      <div className="flex flex-wrap items-end justify-between gap-4 lg:col-start-2">
        <div>
          <h1 className="text-[2rem] font-semibold leading-tight tracking-display">Alex Chen</h1>
          <p className="text-[15px] text-muted">47, ALS. Right foot drop, adaptive AFO prototype.</p>
        </div>
        <SegmentedControl label="Range" options={ranges} value={range} onChange={setRange} size="sm" />
      </div>
      <SectionNav label="Physician sections" sections={sections} value={section} onChange={setSection} id="physician-sections" />
      <Sections pending={shown !== section}>{content}</Sections>
    </div>
  );
}

