  const t = performance.now(); b.click();
  await new Promise(r => setTimeout(r, 900));
  res.push(`${name}: long [${window.__lt.filter(([at]) => at >= t).map(x => x[1]).join(',')}]`);
}
const idle = []; const t0 = performance.now(); await new Promise(r => setTimeout(r, 3000));
res.push('idle 3s long: ' + window.__lt.filter(([at]) => at >= t0).map(x => x[1]).join(','));
res.join('\n')

