const top = t => [...document.querySelectorAll('header button')].find(b => b.textContent.trim() === t);
const nav = (v,n) => [...[...document.querySelectorAll(`nav[aria-label="${v} sections"] ul`)].find(u=>u.offsetParent).querySelectorAll('button')].find(x=>x.getAttribute('aria-label')===n);
const run = async (label, fn) => { const fr=[]; const po=new PerformanceObserver(l=>l.getEntries().forEach(e=>fr.push(e))); po.observe({type:'long-animation-frame'}); fn(); await new Promise(r=>setTimeout(r,900)); po.disconnect();
 return label + ' ' + document.visibilityState + ': ' + fr.filter(f=>f.duration>50).map(f=>`[dur ${Math.round(f.duration)} block ${Math.round(f.blockingDuration)} render ${Math.round(f.renderStart? f.startTime+f.duration-f.renderStart:0)} style ${Math.round(f.styleAndLayoutStart? f.startTime+f.duration-f.styleAndLayoutStart:0)} scripts: ${f.scripts.map(s=>`${s.invoker}|${Math.round(s.duration)}|${(s.sourceFunctionName||'')}|${(s.sourceURL||'').split('/').pop().slice(0,40)}`).join(' ; ')}]`).join(' '); };
const out=[];
out.push(await run('->phys', ()=>top('Physician').click()));
out.push(await run('->fam', ()=>top('Family').click()));
out.push(await run('week', ()=>nav('Family','Week').click()));
out.push(await run('today', ()=>nav('Family','Today').click()));
out.join('\n')

